using System.Text.Json.Serialization;
using Supabase.Postgrest.Attributes;
using Supabase.Postgrest.Models;

namespace PopcornTracker.Models;

/// <summary>A participant who can pay for tickets or popcorn.</summary>
[Table("people")]
public sealed class Person : BaseModel
{
    // Generated by the database (gen_random_uuid), so never sent on insert
    [PrimaryKey("id", shouldInsert: false)]
    public Guid Id { get; set; }

    [Column("name")]
    public string Name { get; set; } = string.Empty;

    /// <summary>Hex color used for the avatar and chips.</summary>
    [Column("color")]
    public string Color { get; set; } = "#ffc94d";

    /// <summary>Order used for the payment rotation.</summary>
    [Column("sort_order")]
    public int SortOrder { get; set; }

    [Column("created_at", ignoreOnInsert: true, ignoreOnUpdate: true)]
    public DateTimeOffset CreatedAt { get; set; }

    // Not a column: the serializer would otherwise send it to PostgREST
    [JsonIgnore]
    public string Initial => string.IsNullOrWhiteSpace(Name) ? "?" : Name.Trim()[..1].ToUpperInvariant();
}
